import type { Question } from '../../lib/types'

export const cost_tools_questions: Question[] = [
  { id: 'd4-tls-001', domain: 4, topics: ['Cost Explorer', 'filtering', 'grouping'], type: 'single', stem: 'A FinOps team wants to identify the top 5 most expensive AWS services over the past 6 months. Which tool provides this analysis natively?', options: [{ id: 'A', text: 'CloudWatch billing alarms' }, { id: 'B', text: 'AWS Cost Explorer' }, { id: 'C', text: 'AWS Config cost tracking' }, { id: 'D', text: 'CloudTrail financial events' }], correct: ['B'], explanation: 'Cost Explorer is the primary cost visualization and analysis tool. Group by: Service, Region, Account, Tag, Usage Type, etc. Supports daily, monthly, and hourly granularity. Covers up to 12 months of historical data (up to 38 months with extended data). Free to access; advanced query API costs $0.01/query.', distractors: { A: 'CloudWatch billing alarms alert on thresholds — not a historical analysis tool.', C: 'AWS Config tracks resource configurations — not billing/cost data.', D: 'CloudTrail tracks API calls — not financial cost data.' } },
  { id: 'd4-tls-002', domain: 4, topics: ['AWS Budgets', 'alerts', 'types'], type: 'single', stem: 'A company wants to receive an alert when their monthly AWS spend exceeds $10,000. Which service and budget type is appropriate?', options: [{ id: 'A', text: 'CloudWatch billing alert' }, { id: 'B', text: 'AWS Health budget notification' }, { id: 'C', text: 'AWS Budgets' }, { id: 'D', text: 'Cost Explorer cost anomaly alert' }], correct: ['C'], explanation: 'AWS Budgets types: Cost Budget (dollar threshold), Usage Budget (usage quantity), RI/Savings Plan coverage and utilization budgets. Configure alert thresholds at multiple percentages of budget. Alerts go to email or SNS. First 2 budgets/month free, then $0.02/budget/day.', distractors: {
      D: 'Cost Anomaly Detection alerts on unexpected INCREASES — not a fixed absolute threshold alert.',
      A: 'CloudWatch billing alarms exist but AWS Budgets is the purpose-built tool for spend thresholds.',
      B: 'AWS Health provides operational health events — not billing alerts.'
    } },
  { id: 'd4-tls-003', domain: 4, topics: ['Trusted Advisor', 'cost optimization', 'checks'], type: 'single', stem: 'Trusted Advisor identifies underutilized EC2 instances and idle RDS instances. What Business/Enterprise Support plan access is required for all cost optimization checks?', options: [{ id: 'A', text: 'Trusted Advisor is available on all support plans' }, { id: 'B', text: 'Enterprise Support only' }, { id: 'C', text: 'Basic/Developer Support' }, { id: 'D', text: 'Business or Enterprise Support' }], correct: ['D'], explanation: 'Trusted Advisor check availability by support tier: Basic/Developer = 6 core checks only (4 security, 2 fault tolerance). Business/Enterprise = all checks including all cost optimization checks. Cost optimization checks: idle load balancers, underutilized EBS volumes, unassociated Elastic IPs, low utilization EC2, idle RDS, etc.', distractors: {
      C: 'Basic/Developer gets only 6 core checks — not full cost optimization checks.',
      A: 'Trusted Advisor check access is tiered by support plan.',
      B: 'Business Support (not just Enterprise) unlocks full Trusted Advisor.'
    } },
  { id: 'd4-tls-004', domain: 4, topics: ['Compute Optimizer', 'recommendations'], type: 'single', stem: 'A company wants right-sizing recommendations for EC2 instances based on actual utilization metrics. Which service provides this without manual analysis?', options: [{ id: 'A', text: 'AWS Compute Optimizer' }, { id: 'B', text: 'AWS Cost Explorer rightsizing recommendations' }, { id: 'C', text: 'CloudWatch Container Insights' }, { id: 'D', text: 'AWS Trusted Advisor underutilized instances check' }], correct: ['A'], explanation: 'AWS Compute Optimizer analyzes utilization of: EC2 instances, EC2 Auto Scaling groups, EBS volumes, Lambda functions, ECS on Fargate. Uses ML over 14 days of CloudWatch data. Free tier available; Enhanced Infrastructure Metrics extends lookback to 3 months ($0.0003360/resource/hour). Provides percentile-based recommendations.', distractors: {
      B: 'Cost Explorer rightsizing uses simpler utilization checks — Compute Optimizer is ML-based and more comprehensive.',
      D: 'Trusted Advisor flags underutilized instances but doesn\'t provide ML-based specific replacement recommendations.',
      C: 'Container Insights is for monitoring — not rightsizing recommendations.'
    } },
  { id: 'd4-tls-005', domain: 4, topics: ['Cost Anomaly Detection', 'ML', 'alerts'], type: 'single', stem: 'AWS spending suddenly spikes 500% due to a misconfigured Auto Scaling policy. What service detects this automatically without a predefined threshold?', options: [{ id: 'A', text: 'AWS Budgets at 100% threshold' }, { id: 'B', text: 'CloudWatch billing alarms' }, { id: 'C', text: 'AWS Cost Anomaly Detection' }, { id: 'D', text: 'AWS Config cost rules' }], correct: ['C'], explanation: 'Cost Anomaly Detection uses ML to detect unexpected spend. No threshold to configure — it learns normal patterns. Can monitor: by AWS service, linked accounts, cost categories, or cost allocation tags. Alerts via email or SNS. Free service — no per-alert charge. Catches anomalies that fixed-threshold alerts miss (e.g., normal spend increase at month end vs. true anomaly).', distractors: {
      A: 'Budgets require a predefined dollar threshold — can\'t detect anomalies below the threshold.',
      B: 'CloudWatch billing alarms use fixed thresholds — not ML-based anomaly detection.',
      D: 'AWS Config tracks resource compliance — not cost anomaly detection.'
    } },
  { id: 'd4-tls-006', domain: 4, topics: ['Cost Allocation Tags', 'activation', 'reporting'], type: 'single', stem: 'A company applies tags (Environment=prod, Team=engineering) to all resources. The tags don\'t appear in Cost Explorer. What step is missing?', options: [{ id: 'A', text: 'Cost allocation tags must be activated in the AWS Billing console' }, { id: 'B', text: 'Tags must be applied at the AWS Organization level' }, { id: 'C', text: 'Tags only work with AWS-generated cost tags' }, { id: 'D', text: 'Tags appear automatically in Cost Explorer once applied' }], correct: ['A'], explanation: 'Two-step process: (1) Apply tags to resources, (2) Activate cost allocation tags in Billing > Cost Allocation Tags. Activation takes up to 24 hours to appear in Cost Explorer. Two types: AWS-generated tags (e.g., aws:createdBy) and user-defined tags. Up to 500 activated cost allocation tags per account.', distractors: {
      D: 'Tag activation is a required step — tags don\'t auto-appear for billing.',
      B: 'Tag activation is per-account in the Billing console — no org-level requirement.',
      C: 'User-defined tags work perfectly for cost allocation once activated.'
    } },
  { id: 'd4-tls-007', domain: 4, topics: ['Savings Plans', 'Compute', 'vs RI'], type: 'single', stem: 'A company runs a mix of EC2 instance types, Lambda, and Fargate and wants maximum flexibility with commitment discounts. Which commitment type provides the most flexibility?', options: [{ id: 'A', text: 'EC2 Instance Savings Plans' }, { id: 'B', text: 'Standard Reserved Instances' }, { id: 'C', text: 'Convertible Reserved Instances' }, { id: 'D', text: 'Compute Savings Plans' }], correct: ['D'], explanation: 'Savings Plans flexibility: Compute SP > EC2 Instance SP > RIs. Compute SP: EC2 (any family, size, OS, region) + Lambda + Fargate — most flexible, 66% max discount. EC2 Instance SP: specific instance family/region, more flexibility than RIs, up to 72% discount. Commitment is in $/hour for 1 or 3 years.', distractors: {
      A: 'EC2 Instance SP is limited to a specific instance family/region — less flexible than Compute SP.',
      B: 'Standard RIs lock to a specific instance type, size, OS, region — least flexible.',
      C: 'Convertible RIs allow exchanges but still EC2-only and require manual management.'
    } },
  { id: 'd4-tls-008', domain: 4, topics: ['RI utilization', 'coverage', 'reports'], type: 'single', stem: 'A company has Reserved Instances but suspects they\'re being underutilized. What metric and tool shows whether RIs are being fully consumed?', options: [{ id: 'A', text: 'AWS Cost Explorer RI Utilization reports' }, { id: 'B', text: 'CloudWatch EC2 running hours' }, { id: 'C', text: 'Trusted Advisor RI checks' }, { id: 'D', text: 'AWS Budgets RI report' }], correct: ['A'], explanation: 'Cost Explorer provides two RI analysis views: (1) Utilization: % of purchased RI hours consumed — below 70% indicates over-purchasing. (2) Coverage: % of EC2 hours covered by RI — low coverage = opportunity to buy more. Both views available by service, account, and tag.', distractors: {
      B: 'CloudWatch tracks instance metrics — not RI utilization vs. coverage.',
      D: 'AWS Budgets can set RI utilization thresholds/alerts — but Cost Explorer provides the utilization/coverage reports.',
      C: 'Trusted Advisor checks for idle RIs — Cost Explorer provides the utilization percentage reports.'
    } },
  { id: 'd4-tls-009', domain: 4, topics: ['AWS Organizations', 'consolidated billing', 'volume discounts'], type: 'single', stem: 'Multiple AWS accounts in an AWS Organization benefit from consolidated billing. What cost advantage does this provide?', options: [{ id: 'A', text: 'Consolidated billing only shares Reserved Instances' }, { id: 'B', text: 'Consolidated billing aggregates usage across all accounts for volume pricing tiers' }, { id: 'C', text: 'Each account gets discounts independently' }, { id: 'D', text: 'No cost advantage' }], correct: ['B'], explanation: 'AWS Organizations consolidated billing benefits: (1) Volume pricing tiers aggregate across accounts (e.g., combined S3 storage qualifies for lower $/GB tier), (2) RI and Savings Plan sharing across accounts, (3) Free tier shared across org (first account only), (4) Single invoice. Free service — no charge for Organizations.', distractors: {
      C: 'Individual accounts don\'t get volume discounts independently — aggregation is the benefit.',
      A: 'Benefits include volume pricing aggregation, not just RI sharing.',
      D: 'Single invoice is one benefit — volume pricing aggregation is the cost savings benefit.'
    } },
  { id: 'd4-tls-010', domain: 4, topics: ['AWS Budgets', 'actions', 'automated response'], type: 'single', stem: 'A company wants to automatically stop EC2 instances when spending exceeds $5,000/month. What Budget feature enables automated response without custom Lambda?', options: [{ id: 'A', text: 'Budget alerts to email only' }, { id: 'B', text: 'Cost Explorer automation' }, { id: 'C', text: 'EventBridge budget rule' }, { id: 'D', text: 'AWS Budgets Actions' }], correct: ['D'], explanation: 'Budgets Actions supports three action types: (1) Apply IAM policy — restrict permissions when budget exceeded, (2) Apply SCP — block actions org-wide, (3) Target EC2/RDS instances to stop. Actions can be automatic or require approval. Requires IAM role with necessary permissions. Available on all paid support plans.', distractors: {
      A: 'Email-only alerts require manual intervention — Actions provide automated response.',
      C: 'EventBridge can receive budget events but Budgets Actions is the native automated response mechanism.',
      B: 'Cost Explorer is analysis-only — no automation capabilities.'
    } },
  { id: 'd4-tls-011', domain: 4, topics: ['Cost Categories', 'mapping', 'organization'], type: 'single', stem: 'A company wants to group costs by business unit (Engineering, Marketing, Operations) even though resources use inconsistent tagging. What tool maps costs to business categories despite inconsistent tags?', options: [{ id: 'A', text: 'AWS Cost Categories' }, { id: 'B', text: 'Billing Groups in AWS Billing Conductor' }, { id: 'C', text: 'AWS Organizations SCPs for cost segregation' }, { id: 'D', text: 'Cost Explorer custom groups' }], correct: ['A'], explanation: 'Cost Categories map costs to user-defined categories using rule-based matching: match by account, tag key/value, service, charge type. Useful when tagging is inconsistent — map all resources in account 123456 to "Engineering" regardless of tags. Appears as a dimension in Cost Explorer. Up to 50 categories per account.', distractors: {
      C: 'SCPs control permissions — not cost allocation or reporting.',
      D: 'Cost Explorer has filtering/grouping — not persistent category definitions with rule-based mapping.',
      B: 'AWS Billing Conductor is for creating custom billing rates for internal showback — different use case.'
    } },
  { id: 'd4-tls-012', domain: 4, topics: ['S3 Storage Lens', 'analytics', 'cost'], type: 'single', stem: 'A company wants organization-wide visibility into S3 usage: storage by bucket, access patterns, cost drivers. What provides a unified view across all accounts?', options: [{ id: 'A', text: 'S3 bucket metrics per account' }, { id: 'B', text: 'Cost Explorer S3 breakdown' }, { id: 'C', text: 'S3 Storage Lens' }, { id: 'D', text: 'AWS Config S3 inventory' }], correct: ['C'], explanation: 'S3 Storage Lens provides: 1.4TB of storage aggregated metrics, activity metrics (requests, bytes transferred), cost optimization recommendations, multi-region visibility. Free default dashboard; Advanced Metrics ($0.20/million monitored objects) adds CloudWatch publishing and prefix-level detail.', distractors: {
      A: 'Per-account S3 metrics don\'t aggregate across an organization.',
      B: 'Cost Explorer shows S3 spend — not S3 usage analytics like storage by class or access patterns.',
      D: 'AWS Config tracks resource config changes — not S3 analytics.'
    } },
  { id: 'd4-tls-013', domain: 4, topics: ['Savings Plans', 'recommendations', 'purchase'], type: 'single', stem: 'Cost Explorer shows an opportunity to purchase Savings Plans. Where does Cost Explorer recommend Savings Plan commitment amounts?', options: [{ id: 'A', text: 'Cost Explorer Savings Plans Recommendations' }, { id: 'B', text: 'AWS Compute Optimizer Savings Plans tab' }, { id: 'C', text: 'AWS Trusted Advisor Savings Plans check' }, { id: 'D', text: 'Savings Plans must be sized manually' }], correct: ['A'], explanation: 'Cost Explorer Savings Plans Recommendations: choose lookback period (7/30/60 days), term (1/3 year), payment option (all-upfront/partial/no), and Savings Plan type. Recommends hourly commitment and shows estimated monthly savings, coverage after commitment, and break-even point.', distractors: {
      D: 'Cost Explorer provides data-driven Savings Plan recommendations — not manual sizing.',
      C: 'Trusted Advisor provides RI and coverage recommendations — Savings Plans recommendations are in Cost Explorer.',
      B: 'Compute Optimizer handles instance rightsizing — not Savings Plan commitment recommendations.'
    } },
  { id: 'd4-tls-014', domain: 4, topics: ['AWS Pricing Calculator', 'estimate', 'pre-deployment'], type: 'single', stem: 'Before deploying a new application, a solutions architect wants to estimate the monthly cost. What tool builds a cost estimate for a hypothetical architecture?', options: [{ id: 'A', text: 'Cost Explorer (for existing accounts)' }, { id: 'B', text: 'AWS Budgets forecast' }, { id: 'C', text: 'Trusted Advisor pre-deployment check' }, { id: 'D', text: 'AWS Pricing Calculator (calculator.aws)' }], correct: ['D'], explanation: 'AWS Pricing Calculator is for pre-deployment estimates. Add services, configure specs (instance type, storage size, transfer amounts), and it generates a cost estimate. Can export as CSV/PDF. No account required. Distinct from Cost Explorer which analyzes existing account spend.', distractors: {
      A: 'Cost Explorer requires an AWS account with existing usage — not for pre-deployment estimates.',
      B: 'Budgets forecasts future spend based on historical patterns — not for new architectures.',
      C: 'Trusted Advisor analyzes existing resources — not pre-deployment estimates.'
    } },
  { id: 'd4-tls-015', domain: 4, topics: ['Cost Explorer', 'forecasting'], type: 'single', stem: 'A CFO wants to know expected AWS spending for the next 12 months based on current trends. What Cost Explorer feature provides this?', options: [{ id: 'A', text: 'Cost Explorer forecasting' }, { id: 'B', text: 'CloudWatch billing predictions' }, { id: 'C', text: 'Cost Explorer can only show historical data' }, { id: 'D', text: 'AWS Budgets forecast' }], correct: ['A'], explanation: 'Cost Explorer forecast: available for monthly granularity up to 12 months ahead. Shows predicted spend with confidence interval bands. Requires sufficient historical data (minimum 1 month, better with 3+ months). Useful for capacity planning and budget projections.', distractors: {
      C: 'Cost Explorer provides both historical analysis AND forecasting.',
      D: 'AWS Budgets can track actuals vs. budget — forecasting is in Cost Explorer.',
      B: 'CloudWatch doesn\'t provide billing forecasts.'
    } },
  { id: 'd4-tls-016', domain: 4, topics: ['Trusted Advisor', 'service limits', 'quotas'], type: 'single', stem: 'A company is approaching EC2 service limits in us-east-1. What Trusted Advisor check warns about this before hitting the limit?', options: [{ id: 'A', text: 'Trusted Advisor doesn\'t check service limits' }, { id: 'B', text: 'Trusted Advisor Service Limits check' }, { id: 'C', text: 'AWS Config service limit rules' }, { id: 'D', text: 'CloudWatch service limit alarms' }], correct: ['B'], explanation: 'Trusted Advisor Service Limits check (Business/Enterprise Support required): monitors current usage against limits for 50+ services. Flags services at 80%+ of quota. Integrates with Service Quotas console for requesting increases. Also check AWS Service Quotas console for comprehensive quota management.', distractors: { A: 'Service Limits is one of the core Trusted Advisor check categories.', C: 'AWS Config tracks resource configurations — not service quota levels.', D: 'CloudWatch doesn\'t natively monitor service quotas; AWS Service Quotas integrates with CloudWatch Alarms.' } },
  { id: 'd4-tls-017', domain: 4, topics: ['AWS Cost Anomaly Detection', 'monitors', 'configuration'], type: 'single', stem: 'A company wants separate cost anomaly alerts for their production and development environments. How are Cost Anomaly Detection monitors configured?', options: [{ id: 'A', text: 'Anomaly detection monitors all accounts uniformly' }, { id: 'B', text: 'Monitors are configured in CloudWatch' }, { id: 'C', text: 'Create separate monitors: by AWS service, by linked account, by cost category, or by cost allocation tag' }, { id: 'D', text: 'One monitor per AWS account only' }], correct: ['C'], explanation: 'Cost Anomaly Detection monitor types: (1) AWS Services — monitors each service individually, (2) Linked Account — monitors a specific account, (3) Cost Category — monitors a defined category, (4) Cost Allocation Tag — monitors by tag value (e.g., Environment=prod). Configure separate alert thresholds per monitor.', distractors: {
      D: 'Multiple monitor types exist — not limited to per-account.',
      A: 'You can configure per-environment monitors using tags or categories.',
      B: 'Cost Anomaly Detection is in the Cost Management console — not CloudWatch.'
    } },
  { id: 'd4-tls-018', domain: 4, topics: ['AWS Budgets', 'types', 'RI coverage'], type: 'single', stem: 'A company wants to ensure at least 70% of their EC2 usage is covered by Reserved Instances. What budget type monitors RI coverage?', options: [{ id: 'A', text: 'Trusted Advisor RI coverage check' }, { id: 'B', text: 'Cost Explorer RI coverage report with alert' }, { id: 'C', text: 'Cost budget at 70% of EC2 spend' }, { id: 'D', text: 'AWS Budgets RI Coverage Budget' }], correct: ['D'], explanation: 'AWS Budgets budget types: Cost, Usage, RI Utilization, RI Coverage, Savings Plans Utilization, Savings Plans Coverage. RI Coverage Budget: set minimum coverage %, get alert when coverage falls below threshold. Useful for ensuring discount coverage targets are maintained.', distractors: {
      C: 'A cost budget tracks spend — not RI coverage percentage.',
      A: 'Trusted Advisor shows RI recommendations — Budgets can alert when coverage targets are missed.',
      B: 'Cost Explorer has RI coverage reports but can\'t send alerts based on coverage thresholds — use Budgets for that.'
    } },
  { id: 'd4-tls-019', domain: 4, topics: ['Compute Optimizer', 'Lambda', 'rightsizing'], type: 'single', stem: 'Lambda functions are over-provisioned with 3 GB memory but only use 512 MB during execution. What service identifies this waste and recommends optimal memory?', options: [{ id: 'A', text: 'AWS Trusted Advisor Lambda check' }, { id: 'B', text: 'CloudWatch Lambda memory utilization alert' }, { id: 'C', text: 'AWS Compute Optimizer' }, { id: 'D', text: 'Lambda Power Tuning (open source)' }], correct: ['C'], explanation: 'Compute Optimizer analyzes Lambda: looks at P99.5 max memory usage across invocations. Recommends optimal memory setting. Over-provisioning wastes money (Lambda charges per GB-second). Under-provisioning degrades performance (slower execution = more GB-seconds). Compute Optimizer balances both.', distractors: {
      B: 'CloudWatch shows metrics — doesn\'t provide optimization recommendations.',
      D: 'Lambda Power Tuning is an open-source tool for manual testing — Compute Optimizer provides automated recommendations.',
      A: 'Trusted Advisor doesn\'t include Lambda-specific optimization checks — Compute Optimizer does.'
    } },
  { id: 'd4-tls-020', domain: 4, topics: ['Cost Explorer', 'hourly granularity', 'cost'], type: 'single', stem: 'Cost Explorer hourly granularity is needed to identify which hour of the day costs spike. What is the cost of enabling hourly granularity in Cost Explorer?', options: [{ id: 'A', text: '$0.01 per API query; the Cost Explorer console is free to use but the API/advanced features cost; hourly granularity is available in console at no extra charge' }, { id: 'B', text: '$10/month for hourly granularity' }, { id: 'C', text: 'Business Support required for hourly data' }, { id: 'D', text: 'Free' }], correct: ['A'], explanation: 'Cost Explorer pricing: Console access is free. API queries cost $0.01/query. Hourly granularity is available in the console at no extra charge (only daily/monthly by default for up to 14 days). Cost Explorer data is available hourly for the last 14 days, daily for up to 12 months, monthly for up to 38 months.', distractors: {
      D: 'Cost Explorer API queries cost $0.01 each — console is free.',
      B: 'No per-feature monthly fee for Cost Explorer.',
      C: 'Cost Explorer is available to all accounts regardless of support plan.'
    } },
  { id: 'd4-tls-021', domain: 4, topics: ['AWS Billing', 'invoice', 'linked accounts'], type: 'single', stem: 'An organization with 50 linked accounts wants each business unit to see only their own cost and usage data in the Billing console. What enables this per-account access?', options: [{ id: 'A', text: 'Linked accounts automatically see consolidated data' }, { id: 'B', text: 'IAM cost viewer policy on each linked account' }, { id: 'C', text: 'Organizations cannot restrict billing visibility' }, { id: 'D', text: 'AWS Organizations management account enables "Consolidated Billing with member account access"' }], correct: ['D'], explanation: 'AWS Organizations management account can enable member account access to billing data. Then each member account\'s IAM users/roles with billing permissions (aws-portal:ViewBilling) can see their own account\'s data in Cost Explorer. Management account sees aggregated and per-account data.', distractors: {
      A: 'Linked accounts don\'t automatically have access to billing data — access must be enabled.',
      B: 'IAM billing policies are part of the solution but the organization-level access must be enabled first.',
      C: 'Organizations does provide mechanisms for per-account billing visibility.'
    } },
  { id: 'd4-tls-022', domain: 4, topics: ['Compute Optimizer', 'EBS', 'volume optimization'], type: 'single', stem: 'EBS volumes are provisioned with 5,000 IOPS but CloudWatch shows average of 200 IOPS consumed. What service recommends optimal EBS volume type and IOPS?', options: [{ id: 'A', text: 'AWS Compute Optimizer' }, { id: 'B', text: 'Cost Explorer EBS analysis' }, { id: 'C', text: 'AWS Config EBS performance rule' }, { id: 'D', text: 'Trusted Advisor EBS volume check' }], correct: ['A'], explanation: 'Compute Optimizer for EBS: analyzes IOPS and throughput utilization, recommends right-sized gp2/gp3/io1/io2 volumes. Over-provisioned io1 volumes (5,000 IOPS but using 200) should downgrade to gp3 — significant cost savings. Looks at peak utilization to avoid performance degradation.', distractors: {
      B: 'Cost Explorer shows EBS spend — not utilization-based optimization recommendations.',
      D: 'Trusted Advisor checks for idle EBS volumes — not IOPS optimization.',
      C: 'AWS Config checks configuration compliance — not performance optimization.'
    } },
  { id: 'd4-tls-023', domain: 4, topics: ['cost optimization', 'tagging strategy', 'governance'], type: 'multi', stem: 'A company is implementing a tagging strategy for cost allocation. Which TWO AWS services enforce tagging compliance and report on untagged resources?', options: [{ id: 'A', text: 'AWS Cost Explorer tag filter' }, { id: 'B', text: 'AWS Resource Groups Tag Editor' }, { id: 'C', text: 'AWS Config with required-tags rule' }, { id: 'D', text: 'AWS IAM tag-based policies' }], correct: ['C', 'B'], explanation: 'AWS Config required-tags managed rule: automatically flags resources that don\'t have required tags — triggers non-compliant findings for remediation. Tag Editor: bulk view and edit tags across all resources in a region, identify untagged resources, bulk-apply tags. Together they enforce and audit tag compliance.', distractors: {
      A: 'Cost Explorer uses tags for filtering/grouping — doesn\'t enforce or audit tagging compliance.',
      D: 'IAM tag-based policies restrict what tags users can manage — not for auditing missing tags.'
    } },
  { id: 'd4-tls-024', domain: 4, topics: ['AWS Cost Explorer', 'API', 'programmatic'], type: 'single', stem: 'A company wants to automate monthly cost reports by service and send to Slack. What programmatic access does Cost Explorer provide?', options: [{ id: 'A', text: 'CloudWatch Cost metrics API' }, { id: 'B', text: 'S3 billing export only' }, { id: 'C', text: 'Cost Explorer API (GetCostAndUsage, GetCostForecast, GetSavingsPlansPurchaseRecommendation)' }, { id: 'D', text: 'Cost Explorer data can only be accessed via console' }], correct: ['C'], explanation: 'Cost Explorer API key calls: GetCostAndUsage (historical), GetCostForecast (predictions), GetReservationUtilization, GetSavingsPlansUtilization, GetRightsizingRecommendation, etc. Each API call costs $0.01. Build Lambda → Cost Explorer API → Slack integration for automated weekly/monthly reports.', distractors: {
      D: 'Cost Explorer provides a full programmatic API.',
      A: 'CloudWatch doesn\'t expose billing cost metrics — Cost Explorer API is the programmatic interface.',
      B: 'S3 Cost and Usage Reports (CUR) are a detailed billing export but Cost Explorer API provides pre-aggregated queries.'
    } },
  { id: 'd4-tls-025', domain: 4, topics: ['Cost and Usage Report', 'CUR', 'detailed billing'], type: 'single', stem: 'A FinOps team needs line-item billing data for every AWS resource hour-by-hour to build custom dashboards in Athena. What AWS service provides this granular billing data?', options: [{ id: 'A', text: 'Cost Explorer API with hourly granularity' }, { id: 'B', text: 'CloudWatch billing metrics' }, { id: 'C', text: 'AWS Billing Invoice PDF' }, { id: 'D', text: 'AWS Cost and Usage Reports (CUR)' }], correct: ['D'], explanation: 'CUR is the most detailed billing data source: resource-level, hourly granularity, 30+ columns (usage type, operation, region, resource ID, tags, RI amortization). Delivered to S3 daily. Query with Athena for custom dashboards. Free to set up — pay only for S3 storage and Athena queries.', distractors: {
      A: 'Cost Explorer API provides aggregated data — CUR provides raw line-item detail at resource level.',
      C: 'Invoice PDF is a summary document — not queryable line-item data.',
      B: 'CloudWatch billing metrics provide account totals — not resource-level line items.'
    } },
  { id: 'd4-tls-026', domain: 4, topics: ['Trusted Advisor', 'security', 'cost'], type: 'single', stem: 'A Basic Support plan account wants to check for exposed S3 buckets. What Trusted Advisor security checks are available on Basic Support?', options: [{ id: 'A', text: 'Only cost optimization checks on Basic Support' }, { id: 'B', text: 'All Trusted Advisor security checks are available on Basic Support' }, { id: 'C', text: 'Basic Support includes 4 core security checks: S3 bucket permissions, security groups unrestricted access, IAM use, MFA on root account' }, { id: 'D', text: 'No security checks on Basic Support' }], correct: ['C'], explanation: 'Basic/Developer Support Trusted Advisor: 6 core checks total. Security (4): S3 Bucket Permissions (public access), Security Groups specific ports unrestricted, IAM use, MFA on root account. Fault Tolerance (2): EBS snapshots, RDS Multi-AZ. All other categories require Business/Enterprise Support.', distractors: {
      B: 'Business/Enterprise Support is required for the full set of Trusted Advisor checks.',
      D: 'Basic Support does include 4 security checks.',
      A: 'Basic Support includes security checks — not just cost optimization (which actually requires Business/Enterprise).'
    } },
  { id: 'd4-tls-027', domain: 4, topics: ['AWS Budgets', 'multi-account', 'organization'], type: 'single', stem: 'An AWS Organizations management account wants to set a combined budget across all linked accounts in a specific OU. What budget scope enables this?', options: [{ id: 'A', text: 'Use separate budget per linked account and aggregate alerts' }, { id: 'B', text: 'AWS Budgets at the management account level can filter by Linked Account (select multiple accounts) or by OU to create organization-wide or OU-scoped budgets' }, { id: 'C', text: 'Budgets can only be set per individual account' }, { id: 'D', text: 'Budgets in Service Control Policies' }], correct: ['B'], explanation: 'Organization budgets: management account creates budgets that span multiple linked accounts. Filter options include: Linked Account (multi-select), OU, Service, Region, Tag, Usage Type. Enables chargeback/showback per OU. Management account is charged for budgets across all accounts.', distractors: {
      C: 'Organization-wide and OU-scoped budgets are supported from the management account.',
      A: 'Individual per-account budgets work but organization-scoped budgets are more manageable.',
      D: 'SCPs control permissions — not cost budgets.'
    } },
  { id: 'd4-tls-028', domain: 4, topics: ['Compute Optimizer', 'Auto Scaling', 'group recommendations'], type: 'single', stem: 'An EC2 Auto Scaling group consistently runs at 20% average CPU across 10 instances. What does Compute Optimizer recommend?', options: [{ id: 'A', text: 'Compute Optimizer analyzes EC2 Auto Scaling groups and recommends: optimal instance type for the group, and whether desired capacity can be reduced; may suggest smaller instances or fewer instances' }, { id: 'B', text: 'Switch to Spot instances' }, { id: 'C', text: 'Increase the Auto Scaling group maximum' }, { id: 'D', text: 'Compute Optimizer doesn\'t analyze Auto Scaling groups' }], correct: ['A'], explanation: 'Compute Optimizer for Auto Scaling groups: analyzes the aggregated utilization of instances in the group. Recommends right-sized instance type for the launch configuration/template. If average CPU is 20%, instances may be oversized. Recommendations include finding ratio (% of over/under-provisioned members).', distractors: {
      D: 'EC2 Auto Scaling groups are one of the five resource types Compute Optimizer analyzes.',
      C: 'Recommending to increase the maximum doesn\'t help with cost at low utilization.',
      B: 'Compute Optimizer focuses on instance type recommendations — Spot vs. On-Demand is a separate pricing decision.'
    } },
  { id: 'd4-tls-029', domain: 4, topics: ['cost optimization', 'idle resources', 'Trusted Advisor'], type: 'multi', stem: 'Trusted Advisor identifies several types of idle resources. Which TWO are checked in the cost optimization category?', options: [{ id: 'A', text: 'Idle load balancers (no active connections in last 30 days)' }, { id: 'B', text: 'Orphaned EBS snapshots older than 90 days' }, { id: 'C', text: 'Lambda functions not invoked in 30 days' }, { id: 'D', text: 'Unassociated Elastic IP addresses' }], correct: ['A', 'D'], explanation: 'Trusted Advisor cost optimization checks include: Idle Load Balancers (no active connections), Unassociated Elastic IPs ($0.005/hour when idle), Underutilized EBS Volumes, Low Utilization EC2 Instances, Idle RDS DB Instances, Underutilized Redshift Clusters.', distractors: {
      B: 'Orphaned snapshot cleanup is possible with Data Lifecycle Manager — not a specific Trusted Advisor cost check.',
      C: 'Trusted Advisor doesn\'t have a Lambda idle check — Lambda has minimal idle cost anyway.'
    } },
  { id: 'd4-tls-030', domain: 4, topics: ['Cost Explorer', 'amortized', 'blended', 'costs'], type: 'single', stem: 'An organization pays all-upfront for Reserved Instances. The bill shows $0 for RI EC2 charges but cost reports are needed that reflect the effective hourly cost. What Cost Explorer cost type shows this?', options: [{ id: 'A', text: 'Unblended costs' }, { id: 'B', text: 'Amortized costs' }, { id: 'C', text: 'Blended costs' }, { id: 'D', text: 'On-demand equivalent cost' }], correct: ['B'], explanation: 'Cost Explorer cost types: Unblended = actual charges on bill ($0 for paid RIs in the month). Amortized = upfront RI fees distributed over the term ($1,200 all-upfront 1-year RI → $100/month amortized). Use amortized for accurate internal showback/chargeback reporting. Blended averages per-account costs in consolidated billing.', distractors: { A: 'Unblended shows $0 for months after paying all-upfront — not useful for showback.', C: 'Blended averages costs across accounts in consolidated billing — not for amortizing upfront fees.', D: 'On-demand equivalent shows what you\'d pay without RIs — useful for savings calculation, not showback.' } },
  { id: 'd4-tls-031', domain: 4, topics: ['cost governance', 'preventive controls', 'SCPs'], type: 'single', stem: 'A company wants to prevent any account in an OU from launching EC2 instances in expensive regions (ap-southeast-1 costs 20% more). What implements this preventive cost control?', options: [{ id: 'A', text: 'IAM policy restricting regions per user' }, { id: 'B', text: 'Cost Explorer region filter' }, { id: 'C', text: 'Service Control Policy (SCP) in AWS Organizations' }, { id: 'D', text: 'AWS Budgets with region filter' }], correct: ['C'], explanation: 'SCPs are preventive cost controls: deny expensive regions, deny large instance types, deny non-approved services. Applies to entire OU or account hierarchy. Unlike budgets (detective — alerts after spending), SCPs prevent the action. Use Condition: aws:RequestedRegion in deny statement.', distractors: {
      D: 'Budgets alert after spending — don\'t prevent launching instances.',
      A: 'IAM policies per-user can restrict regions but SCPs apply org-wide without per-user configuration.',
      B: 'Cost Explorer is analysis-only — no preventive controls.'
    } },
  { id: 'd4-tls-032', domain: 4, topics: ['AWS Billing Conductor', 'showback', 'chargeback'], type: 'single', stem: 'A company wants to create custom pricing rates for internal chargeback — billing business units at $0.10/GB for S3 even though AWS charges $0.023/GB. What service enables custom billing rates?', options: [{ id: 'A', text: 'AWS Budgets with custom pricing' }, { id: 'B', text: 'Organizations consolidated billing' }, { id: 'C', text: 'Cost Categories with markup rules' }, { id: 'D', text: 'AWS Billing Conductor' }], correct: ['D'], explanation: 'AWS Billing Conductor: create custom pricing for internal billing. Pricing rules: custom rates (fixed or % markup/discount over AWS rate), tiering, credits. Billing groups associate accounts with a pricing rule set. Generates pro forma (hypothetical) invoices — doesn\'t change actual AWS charges. Used for ISV/MSP billing or internal chargeback with custom rates.', distractors: {
      C: 'Cost Categories group costs — don\'t apply custom pricing rates.',
      A: 'Budgets track spend against thresholds — not custom pricing.',
      B: 'Consolidated billing shares discounts — doesn\'t create custom pricing rules.'
    } },
  { id: 'd4-tls-033', domain: 4, topics: ['cost optimization', 'review cycle', 'Well-Architected'], type: 'single', stem: 'A company wants to embed cost optimization into their development lifecycle. Which AWS framework provides cost optimization best practices and review tooling?', options: [{ id: 'A', text: 'AWS Cost Explorer recommendations' }, { id: 'B', text: 'AWS Cloud Adoption Framework (CAF)' }, { id: 'C', text: 'AWS Well-Architected Framework' }, { id: 'D', text: 'AWS Trusted Advisor reviews' }], correct: ['C'], explanation: 'AWS Well-Architected Framework Cost Optimization Pillar: 5 design principles, 9 best practice areas (cloud financial management, expenditure/usage awareness, cost-effective resources, manage demand, optimize over time). Well-Architected Tool: self-service workload reviews, identifies HRIs (High Risk Issues), tracks improvement plan.', distractors: {
      B: 'CAF addresses organizational cloud adoption readiness — not architecture cost optimization reviews.',
      D: 'Trusted Advisor is automated checks — Well-Architected Tool is a structured review framework.',
      A: 'Cost Explorer provides data analysis — Well-Architected Tool provides structured best practice reviews.'
    } },
  { id: 'd4-tls-034', domain: 4, topics: ['Savings Plans', 'coverage', 'utilization', 'monitoring'], type: 'single', stem: 'A company bought $10/hour Compute Savings Plan commitment but is only using $6/hour on average. What report shows this underutilization?', options: [{ id: 'A', text: 'Cost Explorer RI utilization report' }, { id: 'B', text: 'Cost Explorer Savings Plans Utilization report' }, { id: 'C', text: 'AWS Budgets Savings Plans utilization budget' }, { id: 'D', text: 'Trusted Advisor Savings Plans check' }], correct: ['B'], explanation: 'Savings Plans Utilization report in Cost Explorer: shows how much of committed $/hour is being used. Low utilization = over-committed (unused commitment wastes money). Also set a Savings Plans Utilization Budget in AWS Budgets to receive alerts when utilization drops below target (e.g., 80%).', distractors: { A: 'RI utilization is a separate report — Savings Plans have their own utilization view.', C: 'Budgets can alert on low utilization — Cost Explorer provides the analysis report.', D: 'Trusted Advisor doesn\'t have a Savings Plans utilization check — use Cost Explorer.' } },
  { id: 'd4-tls-035', domain: 4, topics: ['cost optimization', 'automation', 'Lambda', 'scheduling'], type: 'single', stem: 'EC2 instances used for development run 24/7 but developers only work 10 hours/day, 5 days/week. What reduces compute costs by ~70% without manual intervention?', options: [{ id: 'A', text: 'AWS Instance Scheduler' }, { id: 'B', text: 'Use Savings Plans for dev instances' }, { id: 'C', text: 'Switch to smaller instance types' }, { id: 'D', text: 'Use Spot instances for dev environments' }], correct: ['A'], explanation: 'AWS Instance Scheduler solution: CloudFormation template + Lambda + DynamoDB. Tag instances with schedule (e.g., dev-hours: Mon-Fri 08:00-18:00). Lambda evaluates tags and stops/starts accordingly. 50 active hours/week vs. 168/week = ~70% reduction. AWS-provided solution, not a billable service.', distractors: {
      D: 'Spot instances could be cheaper per hour but don\'t address the idle-time problem.',
      B: 'Savings Plans require commitment for the full reserved hours — not useful for intermittent dev workloads.',
      C: 'Smaller instances reduce per-hour cost but don\'t eliminate idle-time waste.'
    } },
  { id: 'd4-tls-036', domain: 4, topics: ['cost anomaly', 'alert threshold', 'false positives'], type: 'single', stem: 'Cost Anomaly Detection generates too many alerts for normal month-end billing spikes (first of month, invoices close). How can alert noise be reduced?', options: [{ id: 'A', text: 'Disable Cost Anomaly Detection' }, { id: 'B', text: 'Anomaly Detection cannot be tuned' }, { id: 'C', text: 'Move to Budgets alerts instead' }, { id: 'D', text: 'Increase the anomaly alert threshold' }], correct: ['D'], explanation: 'Cost Anomaly Detection alert tuning: set minimum anomaly impact as a dollar amount (e.g., only alert if anomaly > $500) or percentage (>20% above expected). This filters out normal fluctuations while alerting on truly significant anomalies. Review weekly digest instead of individual alerts for lower-severity monitoring.', distractors: {
      A: 'Disabling defeats the purpose — tune the thresholds instead.',
      B: 'Alert thresholds are configurable — both minimum dollar amount and percentage.',
      C: 'Budgets require predefined thresholds — anomaly detection\'s ML-based approach is better for dynamic patterns.'
    } },
  { id: 'd4-tls-037', domain: 4, topics: ['AWS Trusted Advisor', 'notification', 'weekly digest'], type: 'single', stem: 'A DevOps team wants weekly Trusted Advisor findings sent automatically to their email without logging into the console. What enables this?', options: [{ id: 'A', text: 'Trusted Advisor notification settings' }, { id: 'B', text: 'CloudWatch Events Trusted Advisor rule' }, { id: 'C', text: 'Trusted Advisor API polling with Lambda' }, { id: 'D', text: 'SNS subscription for Trusted Advisor' }], correct: ['A'], explanation: 'Trusted Advisor weekly email notifications: enable in Preferences, add email addresses, configure which check categories to include. Sends weekly digest of checks that changed from OK to warning/error or vice versa. Also: EventBridge (CloudWatch Events) publishes TA state change events for automated workflows.', distractors: {
      B: 'EventBridge can receive TA events for custom automation — but the built-in weekly digest is the simplest solution.',
      D: 'SNS integration requires EventBridge + SNS setup — the built-in digest is simpler.',
      C: 'API polling works but the native weekly digest is the purpose-built solution.'
    } },
  { id: 'd4-tls-038', domain: 4, topics: ['cost optimization', 'reporting', 'cadence'], type: 'single', stem: 'A company wants to implement a cloud cost governance program. What is the recommended minimum review cadence for AWS spend?', options: [{ id: 'A', text: 'Annual review' }, { id: 'B', text: 'Daily review of every resource' }, { id: 'C', text: 'Weekly operational reviews (tactical) + monthly trend reviews + quarterly optimization sprints' }, { id: 'D', text: 'Review only when costs exceed budget' }], correct: ['C'], explanation: 'AWS Well-Architected cost optimization recommends: daily/weekly anomaly monitoring (Cost Anomaly Detection), monthly cost reviews (Cost Explorer trends), quarterly optimization reviews (rightsizing, RI/SP review, architecture review). Different cadences match different action types and decision-making speeds.', distractors: {
      A: 'Annual reviews miss optimization opportunities — cloud costs evolve continuously.',
      B: 'Daily individual resource review is impractical — automate anomaly detection instead.',
      D: 'Reactive review only when exceeding budget is too late — proactive optimization prevents overspend.'
    } },
  { id: 'd4-tls-039', domain: 4, topics: ['Cost Explorer', 'resource-level', 'granularity'], type: 'single', stem: 'A team wants to track costs by individual EC2 instance ID over the past month. What Cost Explorer feature enables resource-level tracking?', options: [{ id: 'A', text: 'Enable Cost Explorer resource-level data in preferences; then filter by Resource ID; allows per-instance, per-bucket, per-volume cost tracking (requires opt-in, incurs additional $0.01/resource/month)' }, { id: 'B', text: 'Resource-level data requires CUR (Cost and Usage Reports)' }, { id: 'C', text: 'CloudWatch billing metrics per resource' }, { id: 'D', text: 'Cost Explorer only shows service-level costs' }], correct: ['A'], explanation: 'Cost Explorer resource-level data: opt-in feature that tracks costs per resource ID. Enables filtering/grouping by EC2 instance ID, S3 bucket, EBS volume, etc. Requires opting in (Billing preferences → Cost Explorer → Enable resource-level data). CUR also provides resource-level data with more detail.', distractors: {
      D: 'Cost Explorer can show resource-level data when the feature is enabled.',
      B: 'Both Cost Explorer (with opt-in) and CUR provide resource-level data — different use cases.',
      C: 'CloudWatch provides utilization metrics — not cost/billing data per resource.'
    } },
  { id: 'd4-tls-040', domain: 4, topics: ['Compute Optimizer', 'opt-in', 'organization'], type: 'single', stem: 'An organization wants Compute Optimizer recommendations across all 30 linked accounts without opting in each account separately. What enables org-wide enrollment?', options: [{ id: 'A', text: 'Compute Optimizer only works for single accounts' }, { id: 'B', text: 'Each account must individually opt in to Compute Optimizer' }, { id: 'C', text: 'From the AWS Organizations management account, enable Compute Optimizer for the entire organization' }, { id: 'D', text: 'Compute Optimizer requires Business Support on each account' }], correct: ['C'], explanation: 'Compute Optimizer org-wide enrollment: management account uses OptInOrganization to enroll all member accounts. Member accounts can\'t opt out individually once org-enrolled. Recommendations aggregated at org level. Enhanced Infrastructure Metrics (paid) can also be enabled at org level.', distractors: {
      B: 'Org-wide enrollment from the management account eliminates per-account opt-in.',
      D: 'No specific support plan required for Compute Optimizer — any account can use it.',
      A: 'Compute Optimizer supports both single-account and org-wide deployment.'
    } },
  { id: 'd4-tls-041', domain: 4, topics: ['cost optimization', 'data transfer', 'Cost Explorer'], type: 'single', stem: 'AWS bill shows $5,000/month in data transfer charges but the breakdown is unclear. How does Cost Explorer reveal where data transfer costs originate?', options: [{ id: 'A', text: 'Only CUR provides data transfer breakdown' }, { id: 'B', text: 'Filter Cost Explorer by Service = EC2 or CloudFront, then group by Usage Type' }, { id: 'C', text: 'Data transfer cannot be broken down in Cost Explorer' }, { id: 'D', text: 'Trusted Advisor data transfer report' }], correct: ['B'], explanation: 'Cost Explorer usage type breakdown reveals data transfer sources: DataTransfer-Out-Bytes (internet egress), DataTransfer-Regional-Bytes (inter-AZ), DataTransfer-InterRegion-Out (cross-region). Filter by service to see which services drive transfer costs. VPC Flow Logs for network-level visibility.', distractors: {
      C: 'Cost Explorer usage type grouping does reveal data transfer breakdowns.',
      A: 'CUR provides more granular data but Cost Explorer usage types identify the major categories.',
      D: 'Trusted Advisor doesn\'t provide data transfer analysis reports.'
    } },
  { id: 'd4-tls-042', domain: 4, topics: ['cost optimization', 'lifecycle', 'tagging', 'automation'], type: 'single', stem: 'Development environment resources are provisioned but often not cleaned up after a project ends. What automated process reduces this waste?', options: [{ id: 'A', text: 'Tag resources with expiry dates (e.g., ExpiresOn=2026-07-30); EventBridge Scheduler triggers Lambda to identify expired-tag resources; send cleanup notifications or auto-terminate' }, { id: 'B', text: 'AWS Config max resource age rule' }, { id: 'C', text: 'Manual resource audit monthly' }, { id: 'D', text: 'Trusted Advisor idle resource alerts (weekly)' }], correct: ['A'], explanation: 'Lifecycle tagging pattern: require ExpiresOn or CostCenter tags at resource creation. EventBridge Scheduler + Lambda queries resources by tag, compares to current date, sends Slack/email notification 7 days before expiry, auto-terminates on expiry. Combined with tag enforcement (Config, SCPs) creates a full lifecycle governance loop.', distractors: {
      D: 'Trusted Advisor weekly alerts are after-the-fact — lifecycle tags prevent orphaned resources proactively.',
      C: 'Manual audits are error-prone and slow — automation handles scale.',
      B: 'AWS Config tracks configuration — doesn\'t natively support date-based lifecycle actions.'
    } },
  { id: 'd4-tls-043', domain: 4, topics: ['Savings Plans', 'purchase process', 'Compute Optimizer'], type: 'single', stem: 'Compute Optimizer recommends purchasing a Savings Plan. Where can Savings Plans be purchased in AWS?', options: [{ id: 'A', text: 'AWS Marketplace only' }, { id: 'B', text: 'Contact AWS Sales for Savings Plans' }, { id: 'C', text: 'Compute Optimizer purchases Savings Plans automatically' }, { id: 'D', text: 'AWS Billing and Cost Management console → Savings Plans; or via AWS Savings Plans API; 1-year or 3-year commitment, all-upfront/partial/no-upfront payment options' }], correct: ['D'], explanation: 'Savings Plans purchased through Billing and Cost Management console. Types: Compute (most flexible), EC2 Instance (higher discount), SageMaker SP. Terms: 1-year (lower discount) or 3-year (higher discount). Payment: All Upfront (max discount), Partial Upfront, No Upfront (least discount). Takes effect immediately after purchase.', distractors: {
      A: 'Savings Plans are purchased through the Billing console — not AWS Marketplace.',
      B: 'Self-service through Billing console — no need to contact Sales.',
      C: 'Compute Optimizer recommends — does not automatically purchase commitments.'
    } },
  { id: 'd4-tls-044', domain: 4, topics: ['cost optimization', 'Well-Architected', 'review'], type: 'single', stem: 'A cost review identifies that EC2 instance types are chosen for peak load but average utilization is 15%. What Well-Architected Cost Optimization best practice does this violate?', options: [{ id: 'A', text: 'Use Cost-Effective Resources' }, { id: 'B', text: 'Optimize Over Time' }, { id: 'C', text: 'Manage Demand and Supply Resources' }, { id: 'D', text: 'Cloud Financial Management' }], correct: ['A'], explanation: 'Well-Architected Cost Pillar — Use Cost-Effective Resources: right-size based on actual utilization, use elasticity (Auto Scaling, Spot, serverless) to avoid over-provisioning. 15% average CPU suggests either: (1) wrong instance type, (2) no Auto Scaling, (3) inconsistent workload that should use Spot or serverless.', distractors: {
      C: 'Well-Architected recommends MATCHING supply with demand — not always provisioning for peak.',
      D: 'Cloud Financial Management is about measuring and attributing costs — not the right-sizing decision.',
      B: 'Optimize Over Time is about reviewing new service options — not about the fundamental right-sizing principle.'
    } },
  { id: 'd4-tls-045', domain: 4, topics: ['cost tools', 'exam pattern', 'tool selection'], type: 'single', stem: 'Match the cost optimization tool to its primary use case: (1) Find specific cost-saving opportunities now. (2) Detect unexpected spend automatically. (3) Set spend limit alerts. (4) Analyze historical spending trends. What is the correct mapping?', options: [{ id: 'A', text: '1=Cost Explorer, 2=Budgets, 3=Anomaly Detection, 4=Trusted Advisor' }, { id: 'B', text: '1=Budgets, 2=Trusted Advisor, 3=Cost Explorer, 4=Anomaly Detection' }, { id: 'C', text: '1=Trusted Advisor, 2=Cost Anomaly Detection, 3=AWS Budgets, 4=Cost Explorer' }, { id: 'D', text: 'All four tools serve the same purpose' }], correct: ['C'], explanation: 'Tool mapping: Trusted Advisor = proactive specific recommendations (idle resources, low utilization — actionable NOW). Cost Anomaly Detection = automated ML-based anomaly alerting (unexpected patterns). AWS Budgets = threshold-based spend alerts and automated actions. Cost Explorer = historical trend analysis, forecasting, RI/SP analysis. Each tool has a distinct use case on the SAA-C03.', distractors: {
      A: 'Cost Explorer is the historical analysis tool, not Trusted Advisor — Trusted Advisor gives actionable recommendations, not trends.',
      B: 'Budgets sets spending limit alerts — Cost Explorer is for historical analysis.',
      D: 'Each tool has a clearly differentiated primary purpose — critical distinction for the exam.'
    } },
]
